using System;using System.IO;using System.Net;using System.Net.Http;using System.Collections.Generic;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;
namespace EanEtikety {
[DataContract]public sealed class UpdateAsset {[DataMember(Name="id")]public long Id;[DataMember(Name="name")]public string Name;[DataMember(Name="size")]public long Size;[DataMember(Name="digest")]public string Digest;}
[DataContract]public sealed class UpdateRelease {[DataMember(Name="id")]public long Id;[DataMember(Name="tag_name")]public string Tag;[DataMember(Name="target_commitish")]public string Commit;[DataMember(Name="draft")]public bool Draft;[DataMember(Name="prerelease")]public bool Prerelease;[DataMember(Name="assets")]public UpdateAsset[] Assets;}
public sealed class UpdateNetwork:IDisposable {
 const string Api="https://api.github.com/repos/ndxnraw/labeldesigner";readonly HttpClient http;int timeoutMilliseconds=30000;
 public UpdateNetwork():this(new HttpClientHandler{AllowAutoRedirect=false,UseDefaultCredentials=false,UseCookies=false}){}
 public UpdateNetwork(HttpMessageHandler handler){http=new HttpClient(handler,true);http.Timeout=Timeout.InfiniteTimeSpan;http.DefaultRequestHeaders.UserAgent.ParseAdd("ND-LabelDesigner-Pre-release");}
 public static bool AllowedUrl(Uri url){if(url==null||url.Scheme!="https"||!url.IsDefaultPort||url.UserInfo.Length!=0)return false;return url.Host=="api.github.com"||url.Host=="github.com"||url.Host=="release-assets.githubusercontent.com"||url.Host=="objects.githubusercontent.com";}
 T Wait<T>(Task<T> task,CancellationTokenSource cancel){var clock=Stopwatch.StartNew();try{while(!task.IsCompleted){WorkContext.Check();if(clock.ElapsedMilliseconds>timeoutMilliseconds)throw new IOException(Loc.T("Čas pripojenia vypršal."));Thread.Sleep(25);}return task.GetAwaiter().GetResult();}catch{cancel.Cancel();task.ContinueWith(t=>{var ignored=t.Exception;},TaskContinuationOptions.OnlyOnFaulted);throw;}}
 HttpResponseMessage Open(Uri url,bool binary,CancellationTokenSource cancel){for(int i=0;i<6;i++){WorkContext.Check();if(!AllowedUrl(url))throw new InvalidDataException("Untrusted update URL.");using(var request=new HttpRequestMessage(HttpMethod.Get,url)){request.Headers.Accept.ParseAdd(binary?"application/octet-stream":"application/vnd.github+json");request.Headers.Add("X-GitHub-Api-Version","2022-11-28");var response=Wait(http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,cancel.Token),cancel);int code=(int)response.StatusCode;if(code==301||code==302||code==303||code==307||code==308){var location=response.Headers.Location;response.Dispose();if(location==null)throw new InvalidDataException("Missing redirect target.");url=location.IsAbsoluteUri?location:new Uri(url,location);continue;}if(!response.IsSuccessStatusCode){response.Dispose();throw new IOException(Loc.T("Aktualizácie nie sú dostupné. Skontrolujte pripojenie a skúste to znova.")+" ("+code+")");}return response;}}throw new InvalidDataException("Too many update redirects.");}
 void Read(Uri url,Stream output,long maximum,long expected,bool binary){using(var cancel=new CancellationTokenSource())using(var response=Open(url,binary,cancel)){if(response.Content.Headers.ContentLength.HasValue&&(response.Content.Headers.ContentLength.Value>maximum||expected>=0&&response.Content.Headers.ContentLength.Value!=expected))throw new InvalidDataException("Unexpected update response size.");using(var input=Wait(response.Content.ReadAsStreamAsync(),cancel)){var buffer=new byte[32768];long total=0;int count;while((count=Wait(input.ReadAsync(buffer,0,buffer.Length,cancel.Token),cancel))>0){WorkContext.Check();total+=count;if(total>maximum||expected>=0&&total>expected)throw new InvalidDataException("Update response exceeds limit.");output.Write(buffer,0,count);if(binary)WorkContext.Report("Sťahujem aktualizáciu…",(int)total,(int)Math.Max(0,expected));}if(expected>=0&&total!=expected)throw new EndOfStreamException("Incomplete update download.");}}}
 byte[] Bytes(Uri url,long limit,long expected,bool binary){using(var output=new MemoryStream()){Read(url,output,limit,expected,binary);return output.ToArray();}}
 static UpdateAsset Asset(UpdateRelease release,string name){if(release.Assets==null||release.Assets.Length>32)throw new InvalidDataException("Invalid release assets.");UpdateAsset found=null;foreach(var asset in release.Assets)if(asset!=null&&asset.Name==name){if(found!=null||asset.Id<=0||asset.Size<=0||asset.Digest==null||!asset.Digest.StartsWith("sha256:",StringComparison.Ordinal)||!UpdateFiles.Hex(asset.Digest.Substring(7),64))throw new InvalidDataException("Invalid release asset digest.");found=asset;}if(found==null)throw new InvalidDataException(Loc.T("Vydanie zatiaľ nepodporuje riadené aktualizácie. Použite ručne stiahnutý ZIP."));return found;}
 public UpdateOffer Check(string family){if(!UpdateFiles.FamilyValid(family))throw new ArgumentException("family");WorkContext.Check();var bytes=Bytes(new Uri(Api+"/releases/tags/Pre-release"),1024*1024,-1,false);UpdateRelease release;using(var stream=new MemoryStream(bytes))release=(UpdateRelease)new DataContractJsonSerializer(typeof(UpdateRelease)).ReadObject(stream);
  if(release==null||release.Id<=0||release.Tag!="Pre-release"||release.Draft||!release.Prerelease||!UpdateFiles.Hex(release.Commit,40))throw new InvalidDataException("Unexpected release identity.");var indexAsset=Asset(release,"UPDATE-INDEX.xml");if(indexAsset.Size>512*1024)throw new InvalidDataException("Update index too large.");bytes=Bytes(new Uri(Api+"/releases/assets/"+indexAsset.Id),512*1024,indexAsset.Size,true);if(UpdateFiles.Digest(bytes)!=indexAsset.Digest.Substring(7))throw new InvalidDataException("Update index checksum mismatch.");UpdateIndex index;using(var stream=new MemoryStream(bytes))using(var reader=System.Xml.XmlReader.Create(stream,new System.Xml.XmlReaderSettings{DtdProcessing=System.Xml.DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=512*1024}))index=(UpdateIndex)new System.Xml.Serialization.XmlSerializer(typeof(UpdateIndex)).Deserialize(reader);index.Validate();if(index.SourceCommit!=release.Commit)throw new InvalidDataException("Release changed during check.");var offer=index.Packages.Find(p=>p.Family==family);var file=Asset(release,offer.AssetName);if(file.Size!=offer.Size||file.Digest.Substring(7)!=offer.Sha256)throw new InvalidDataException("Package does not match release index.");offer.AssetId=file.Id;return offer;
 }
 public string Download(UpdateOffer offer,string directory){if(offer==null||offer.AssetId<=0||!UpdateFiles.Hex(offer.Sha256,64)||offer.Size<=0||offer.Size>256L*1024*1024)throw new InvalidDataException("Invalid download offer.");Directory.CreateDirectory(directory);string path=Path.Combine(directory,"download-"+Guid.NewGuid().ToString("N")+".zip");try{AtomicOutput.Save(path,temp=>{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None))Read(new Uri(Api+"/releases/assets/"+offer.AssetId),output,256L*1024*1024,offer.Size,true);if(UpdateFiles.Hash(temp)!=offer.Sha256)throw new InvalidDataException("Downloaded ZIP checksum mismatch.");});return path;}catch{if(File.Exists(path))File.Delete(path);throw;}}
 public void Dispose(){http.Dispose();}
}
}
